import java.util.*;
import java.io.*;

public class RPSAlternate {
    public static void main(String[] args) {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        try {
            int n = Integer.parseInt(reader.readLine());
            long[] a = new long[3];
            long[] b = new long[3];
            String[] aInput = reader.readLine().split(" ");
            String[] bInput = reader.readLine().split(" ");
            for (int i = 0; i < 3; i++) {
                a[i] = Long.parseLong(aInput[i]);
            }
            for (int i = 0; i < 3; i++) {
                b[i] = Long.parseLong(bInput[i]);
            }
            long maxWins = Math.min(a[0], b[1]) + Math.min(a[1], b[2]) + Math.min(a[2], b[0]);
            long minLosses = 0;
            minLosses += (a[0] > (b[0] + b[2]) ? -(b[0] + b[2]) + a[0] : 0);
            minLosses += (a[1] > (b[0] + b[1]) ? -(b[0] + b[1]) + a[1] : 0);
            minLosses += (a[2] > (b[1] + b[2]) ? -(b[1] + b[2]) + a[2] : 0);
            System.out.println(minLosses + " " + maxWins);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
